static inline bool xskq_cons_read_desc(struct xsk_queue *q,
^I^I^I^I       struct xdp_desc *desc,
^I^I^I^I       struct xsk_buff_pool *pool)
{
^Iwhile (q->cached_cons != q->cached_prod) {
^I^Istruct xdp_rxtx_ring *ring = (struct xdp_rxtx_ring *)q->ring;
^I^Iu32 idx = q->cached_cons & q->ring_mask;

^I^I*desc = ring->desc[idx];
^I^Iif (xskq_cons_is_valid_desc(q, desc, pool))
^I^I^Ireturn true;

^I^Iq->cached_cons++;
^I}

static inline u32 xskq_cons_read_desc_batch(struct xsk_queue *q, struct xsk_buff_pool *pool,
^I^I^I^I^I    u32 max)
{
^Iu32 cached_cons = q->cached_cons, nb_entries = 0;
^Istruct xdp_desc *descs = pool->tx_descs;

^Iwhile (cached_cons != q->cached_prod && nb_entries < max) {
^I^Istruct xdp_rxtx_ring *ring = (struct xdp_rxtx_ring *)q->ring;
^I^Iu32 idx = cached_cons & q->ring_mask;

^I^Idescs[nb_entries] = ring->desc[idx];
^I^Iif (unlikely(!xskq_cons_is_valid_desc(q, &descs[nb_entries], pool))) {
^I^I^I/* Skip the entry */
^I^I^Icached_cons++;
^I^I^Icontinue;
^I^I}

^I^Inb_entries++;
^I^Icached_cons++;
^I}

^I/* Release valid plus any invalid entries */
^Ixskq_cons_release_n(q, cached_cons - q->cached_cons);
^Ireturn nb_entries;
}

